const getDate=async()=>{try{const e=await fetch("https://timeapi.io/api/Time/current/zone?timeZone=Asia/Manila");if(!e.ok)return null;return(await e.json()).dateTime.slice(0,23)}catch(e){return null}},getTimeOffset=async()=>{const e=await getDate();return e?new Date(e).getTime()-Date.now():0},updateCountdown=(e,t)=>{const n=document.querySelector(".countdown"),o=document.querySelector(".countdown-finished"),i=new Date(Date.now()+t),a=e-i;if(a<=0){const t=new Date(i);t.setHours(0,0,0,0);const a=new Date(e);if(a.setHours(0,0,0,0),t>a){const e=document.querySelector(".finished-text span"),t=document.querySelector(".finished-text h2");e.textContent="With Love & Gratitude",t.textContent="Thank You for Celebrating"}return n.classList.add("hidden"),void o.classList.remove("hidden")}n.classList.remove("hidden"),o.classList.add("hidden");const s=6e4,d=36e5,r=24*d,c=Math.floor(a/r),u=Math.floor(a%r/d),l=Math.floor(a%d/s),m=Math.floor(a%s/1e3);document.getElementById("days").innerText=c,document.getElementById("hours").innerText=u,document.getElementById("minutes").innerText=l,document.getElementById("seconds").innerText=m},runWeddingTimer=e=>{const t=new Date(e).getTime();let n=0;setInterval(()=>{updateCountdown(t,n)},1e3);updateCountdown(t,n),getTimeOffset().then(e=>{n=e})};